import React, { useState, useRef } from 'react';
import { ContextMenu } from 'primereact/contextmenu';
import { useNavigate } from 'react-router-dom';

export default function Router() {
    const cm = useRef(null);
    const navigate = useNavigate();
    const items = [
        {
            label: 'Router Link',
            icon: 'pi pi-palette',
            command: () => {
                navigate('/unstyled');
            }
        },
        {
            label: 'Programmatic',
            icon: 'pi pi-link',
            command: () => {
                navigate('/installation');
            }
        },
        {
            label: 'External',
            icon: 'pi pi-home',
            command: () => {
                window.location.href = 'https://react.dev/';
            }
        }
    ];

    const onRightClick = (event) => {
        cm.current.show(event);
    };

    return (
        <div className="fxb fvc gp2">
            <span className="fxb fvc gp2 bd rds2 w48 h48" onContextMenu={(event) => onRightClick(event)} aria-haspopup="true">
                <img alt="logo" src="https://primefaces.org/cdn/primereact/images/logo.png" height="40"></img>
            </span>
            <ContextMenu model={items} ref={cm} />
        </div>
    )

}